package v1alpha1

import "testing"

func TestRationalRat(t *testing.T) {
	tests := []struct {
		name    string
		value   Rational
		wantNum int64
		wantDen int64
		wantErr bool
	}{
		{name: "zero", value: "0", wantNum: 0, wantDen: 1},
		{name: "integer", value: "60", wantNum: 60, wantDen: 1},
		{name: "rational", value: "60000/1001", wantNum: 60000, wantDen: 1001},
		{name: "unreduced rational", value: "120000/2002", wantNum: 60000, wantDen: 1001},
		{name: "identity denominator rejected", value: "1/1", wantErr: true},
		{name: "plus rejected", value: "+60", wantErr: true},
		{name: "negative rejected", value: "-60", wantErr: true},
		{name: "zero rational rejected", value: "0/1", wantErr: true},
		{name: "decimal rejected", value: "59.94", wantErr: true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := tt.value.Rat()
			if tt.wantErr {
				if err == nil {
					t.Fatalf("Rat() error = nil, want error")
				}
				return
			}
			if err != nil {
				t.Fatalf("Rat() error = %v", err)
			}
			if got.Num().Int64() != tt.wantNum || got.Denom().Int64() != tt.wantDen {
				t.Fatalf("Rat() = %d/%d, want %d/%d", got.Num().Int64(), got.Denom().Int64(), tt.wantNum, tt.wantDen)
			}
		})
	}
}

