func TestGenerateDeploymentUsesConfiguredResourcesAndHighSpeedNetworks(t *testing.T) {
	scheme := runtime.NewScheme()
	if err := examplev1alpha1.AddToScheme(scheme); err != nil {
		t.Fatalf("AddToScheme() error = %v", err)
	}

	owner := &examplev1alpha1.ColorPatternMediaFunction{
		TypeMeta: metav1.TypeMeta{
			APIVersion: examplev1alpha1.GroupVersion.String(),
			Kind:       "ColorPatternMediaFunction",
		},
		ObjectMeta: metav1.ObjectMeta{
			Name:      "sample",
			Namespace: "default",
		},
	}

	deployment, err := GenerateDeployment(DeploymentConfig{
		Name:         "sample",
		Namespace:    "default",
		Labels:       map[string]string{"app": "sample"},
		Command:      []string{"run"},
		Args:         []string{"--flag"},
		Owner:        owner,
		Scheme:       scheme,
		Capabilities: toCapabilities([]string{"IPC_LOCK"}),
		HighSpeedNetwork: examplev1alpha1.HighSpeedNetwork{
			{Name: "media-a-tx-net"},
			{Name: "media-b-tx-net-static", IP: "198.51.100.3/24"},
		},
		Resources: corev1.ResourceRequirements{
			Limits: corev1.ResourceList{
				corev1.ResourceCPU: resource.MustParse("4"),
			},
			Requests: corev1.ResourceList{
				corev1.ResourceCPU: resource.MustParse("2"),
			},
		},
	})
	if err != nil {
		t.Fatalf("GenerateDeployment() error = %v", err)
	}

	gotNetworks := deployment.Spec.Template.Annotations[AnnotationNetworkConfig]
	wantNetworks := `[{"name":"media-a-tx-net"},{"ips":["198.51.100.3/24"],"name":"media-b-tx-net-static"}]`
	if gotNetworks != wantNetworks {
		t.Fatalf("network annotation = %s, want %s", gotNetworks, wantNetworks)
	}

	if len(deployment.Spec.Template.Spec.Containers) == 0 {
		t.Fatalf("GenerateDeployment() produced no containers")
	}
	container := deployment.Spec.Template.Spec.Containers[0]
	if got := container.Resources.Limits.Cpu().String(); got != "4" {
		t.Fatalf("limits.cpu = %s, want 4", got)
	}
	if got := container.Resources.Requests.Cpu().String(); got != "2" {
		t.Fatalf("requests.cpu = %s, want 2", got)
	}
}

func TestGenerateDeploymentDefaultsHighSpeedNetwork(t *testing.T) {
	scheme := runtime.NewScheme()
	if err := examplev1alpha1.AddToScheme(scheme); err != nil {
		t.Fatalf("AddToScheme() error = %v", err)
	}

	owner := &examplev1alpha1.ColorPatternMediaFunction{
		TypeMeta: metav1.TypeMeta{
			APIVersion: examplev1alpha1.GroupVersion.String(),
			Kind:       "ColorPatternMediaFunction",
		},
		ObjectMeta: metav1.ObjectMeta{
			Name:      "sample",
			Namespace: "default",
		},
	}
	base := DeploymentConfig{
		Name:      "sample",
		Namespace: "default",
		Labels:    map[string]string{"app": "sample"},
		Owner:     owner,
		Scheme:    scheme,
	}

	deployment, err := GenerateDeployment(base)
	if err != nil {
		t.Fatalf("GenerateDeployment() error = %v", err)
	}
	if got := deployment.Spec.Template.Annotations[AnnotationNetworkConfig]; got != `[{"name":"media-a-rx-net"}]` {
		t.Fatalf("default network annotation = %s, want media-a-rx-net", got)
	}
	if len(deployment.Spec.Template.Spec.Containers) == 0 {
		t.Fatalf("GenerateDeployment() produced no containers")
	}
	container := deployment.Spec.Template.Spec.Containers[0]
	if got := container.Resources.Limits.Cpu().String(); got != "4" {
		t.Fatalf("default limits.cpu = %s, want 4", got)
	}
	if got := container.Resources.Requests.Memory().String(); got != "2Gi" {
		t.Fatalf("default requests.memory = %s, want 2Gi", got)
	}
}

func TestGenerateDeploymentIgnoresUnsupportedResourceClaims(t *testing.T) {
	scheme := runtime.NewScheme()
	if err := examplev1alpha1.AddToScheme(scheme); err != nil {
		t.Fatalf("AddToScheme() error = %v", err)
	}

	owner := &examplev1alpha1.ColorPatternMediaFunction{
		TypeMeta: metav1.TypeMeta{
			APIVersion: examplev1alpha1.GroupVersion.String(),
			Kind:       "ColorPatternMediaFunction",
		},
		ObjectMeta: metav1.ObjectMeta{
			Name:      "sample",
			Namespace: "default",
		},
	}

	deployment, err := GenerateDeployment(DeploymentConfig{
		Name:      "sample",
		Namespace: "default",
		Labels:    map[string]string{"app": "sample"},
		Owner:     owner,
		Scheme:    scheme,
		Resources: corev1.ResourceRequirements{
			Claims: []corev1.ResourceClaim{{Name: "unsupported-claim"}},
		},
	})
	if err != nil {
		t.Fatalf("GenerateDeployment() error = %v", err)
	}

	container := deployment.Spec.Template.Spec.Containers[0]
	if len(container.Resources.Claims) != 0 {
		t.Fatalf("container resource claims = %v, want none", container.Resources.Claims)
	}
	if got := container.Resources.Limits.Cpu().String(); got != "4" {
		t.Fatalf("limits.cpu = %s, want default 4", got)
	}
}

func TestApplyDeploymentUsesNamespaceSELinuxMCS(t *testing.T) {
	scheme := runtime.NewScheme()
	if err := corev1.AddToScheme(scheme); err != nil {
		t.Fatalf("corev1 AddToScheme() error = %v", err)
	}
	if err := appsv1.AddToScheme(scheme); err != nil {
		t.Fatalf("appsv1 AddToScheme() error = %v", err)
	}
	if err := examplev1alpha1.AddToScheme(scheme); err != nil {
		t.Fatalf("example AddToScheme() error = %v", err)
	}

	owner := &examplev1alpha1.ColorPatternMediaFunction{
		TypeMeta: metav1.TypeMeta{
			APIVersion: examplev1alpha1.GroupVersion.String(),
			Kind:       "ColorPatternMediaFunction",
		},
		ObjectMeta: metav1.ObjectMeta{
			Name:      "sample",
			Namespace: "default",
		},
	}
	namespace := &corev1.Namespace{
		ObjectMeta: metav1.ObjectMeta{
			Name: "default",
			Annotations: map[string]string{
				namespaceSELinuxMCSAnnotation: "s0:c1,c0",
			},
		},
	}
	c := fake.NewClientBuilder().WithScheme(scheme).WithObjects(namespace).Build()

	err := ApplyDeployment(context.Background(), ApplyDeploymentInput{
		Client:   c,
		Recorder: record.NewFakeRecorder(10),
		Scheme:   scheme,
		Owner:    owner,
		AppName:  "color-pattern",
		Spec:     owner.Spec,
		Runtime: RuntimeProfile{
			Image:                  "example.com/mxl-runtime:test",
			UseNamespaceSELinuxMCS: true,
		},
	})
	if err != nil {
		t.Fatalf("ApplyDeployment() error = %v", err)
	}

	deployment := &appsv1.Deployment{}
	if err := c.Get(context.Background(), client.ObjectKey{Namespace: "default", Name: "sample"}, deployment); err != nil {
		t.Fatalf("get deployment: %v", err)
	}
	securityContext := deployment.Spec.Template.Spec.SecurityContext
	if securityContext == nil || securityContext.SELinuxOptions == nil {
		t.Fatalf("expected pod SELinux options")
	}
	if got := securityContext.SELinuxOptions.Level; got != "s0:c1,c0" {
		t.Fatalf("SELinux level = %q, want s0:c1,c0", got)
	}
}

func hasVolume(volumes []corev1.Volume, name string) bool {
	for _, volume := range volumes {
		if volume.Name == name {
			return true
		}
	}
	return false
}

