package v1alpha1

import (
	"fmt"
	"math/big"
	"regexp"

	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
)

// ControlKind identifies the selected control variant.
type ControlKind string

const (
	ControlKindNMOS      ControlKind = "nmos"
	ControlKindSDP       ControlKind = "sdp"
	ControlKindMXLStatic ControlKind = "mxl_static"
)

// NMOSControl selects NMOS as the control plane.
type NMOSControl struct{}

// SDPControl selects inline SDP as the control plane.
type SDPControl struct {
	// Data contains the SDP payload.
	// +kubebuilder:validation:MinLength=1
	Data string `json:"data"`
}

// MXLStaticControl provides static MXL flow parameters, bypassing NMOS flow discovery.
// It lives in control.mxl_static so it is clear this is a control-plane choice,
// not a transport-layer parameter.
type MXLStaticControl struct {
	// MXLDomainID is the MXL domain identifier.
	// +kubebuilder:validation:Required
	MXLDomainID string `json:"mxl_domain_id"`

	// MXLFlowID is the MXL flow identifier.
	// +kubebuilder:validation:Required
	MXLFlowID string `json:"mxl_flow_id"`
}

// Control specifies control-plane configuration for an input/output.
// Exactly one control variant must be specified.
// +kubebuilder:validation:XValidation:rule="[has(self.nmos),has(self.sdp),has(self.mxl_static)].filter(x,x==true).size() == 1",message="exactly one control variant (nmos, sdp, or mxl_static) must be set"
type Control struct {
	// NMOS selects NMOS IS-04/IS-05 as the control plane.
	// +kubebuilder:validation:Optional
	NMOS *NMOSControl `json:"nmos,omitempty"`

	// SDP selects inline SDP as the control plane (RTP transport only).
	// +kubebuilder:validation:Optional
	SDP *SDPControl `json:"sdp,omitempty"`

	// MXLStatic selects static MXL flow parameters, bypassing NMOS flow discovery.
	// Valid for MXL transport only.
	// +kubebuilder:validation:Optional
	MXLStatic *MXLStaticControl `json:"mxl_static,omitempty"`
}

func (c Control) Kind() (ControlKind, error) {
	var kind ControlKind
	count := 0
	if c.NMOS != nil {
		kind = ControlKindNMOS
		count++
	}
	if c.SDP != nil {
		kind = ControlKindSDP
		count++
	}
	if c.MXLStatic != nil {
		kind = ControlKindMXLStatic
		count++
	}
	if count != 1 {
		return "", fmt.Errorf("exactly one control variant (nmos, sdp, or mxl_static) must be set")
	}
	return kind, nil
}

// TransportKind identifies the selected transport variant.
type TransportKind string

const (
	TransportKindRTP TransportKind = "rtp"
	TransportKindMXL TransportKind = "mxl"
)

// RTPTransport selects RTP as transport.
type RTPTransport struct {
	// PacketTime is the RTP packet duration in milliseconds (e.g. 1.0, 0.125).
	// +kubebuilder:validation:Optional
	// +kubebuilder:validation:Minimum=0
	PacketTime float64 `json:"packet_time,omitempty"`
}

// MXLTransport selects MXL as transport.
type MXLTransport struct{}

// Transport specifies media transport configuration.
// Exactly one transport variant must be specified.
// +kubebuilder:validation:XValidation:rule="has(self.rtp) != has(self.mxl)",message="exactly one transport variant (rtp or mxl) must be set"
type Transport struct {
	// RTP selects RTP transport.
	// +kubebuilder:validation:Optional
	RTP *RTPTransport `json:"rtp,omitempty"`

	// MXL selects MXL transport.
	// +kubebuilder:validation:Optional
	MXL *MXLTransport `json:"mxl,omitempty"`
}

func (t Transport) Kind() (TransportKind, error) {
	var kind TransportKind
	count := 0
	if t.RTP != nil {
		kind = TransportKindRTP
		count++
	}
	if t.MXL != nil {
		kind = TransportKindMXL
		count++
	}
	if count != 1 {
		return "", fmt.Errorf("exactly one transport variant (rtp or mxl) must be set")
	}
	return kind, nil
}

var rationalRE = regexp.MustCompile(`^(0|[1-9]\d*(/([2-9]|[1-9]\d+))?)$`)

// Rational represents either zero ("0") or a positive integer/rational
// (e.g. "60", "60000/1001").
// Decimal approximations such as "59.94" are not allowed.
// +kubebuilder:validation:Pattern=`^(0|[1-9]\d*(/([2-9]|[1-9]\d+))?)$`
type Rational string

// Rat parses the Rational into a *big.Rat for exact arithmetic.
// Accepts values such as "60000/1001", "60", or "0".
func (f Rational) Rat() (*big.Rat, error) {
	s := string(f)
	if !rationalRE.MatchString(s) {
		return nil, fmt.Errorf("invalid rational syntax: %q", s)
	}
	r := new(big.Rat)
	if _, ok := r.SetString(s); !ok {
		return nil, fmt.Errorf("invalid rational value: %q", s)
	}
	return r, nil
}

// Parts returns the integer numerator and denominator of the rational.
// For example, "60000/1001" returns (60000, 1001), and "0" returns (0, 1).
func (f Rational) Parts() (num, den int64, err error) {
	r, err := f.Rat()
	if err != nil {
		return 0, 0, err
	}
	return r.Num().Int64(), r.Denom().Int64(), nil
}

// VideoFormat describes video-specific media parameters shared across
// media functions. Operator-specific CRDs can embed this type and layer their
// own schema defaults on top in generated CRDs.
type VideoFormat struct {
	// MediaType is the IANA media type/subtype for this stream (e.g. video/raw, video/jxsv).
	// +kubebuilder:validation:Required
	MediaType string `json:"media_type"`

	// FrameWidth is the video frame width in pixels.
	// +kubebuilder:validation:Required
	FrameWidth int `json:"frame_width"`

	// FrameHeight is the video frame height in pixels.
	// +kubebuilder:validation:Required
	FrameHeight int `json:"frame_height"`

	// FrameRate is the video frame rate in frames per second.
	// Accepts an integer ("60") or a rational "N/D" ("60000/1001").
	// Specific media functions may narrow this to a supported subset with enum-like validation.
	// +kubebuilder:validation:Required
	FrameRate Rational `json:"frame_rate"`

	// InterlaceMode describes the scanning mode, following AMWA IS-04 vocabulary.
	// +kubebuilder:validation:Required
	// +kubebuilder:validation:Enum=progressive;interlaced_tff;interlaced_bff;interlaced_psf
	InterlaceMode string `json:"interlace_mode"`

	// ColorSampling is the color sampling descriptor as used in SDP fmtp.
	// +kubebuilder:validation:Required
	ColorSampling string `json:"color_sampling"`

	// ComponentDepth is the video component bit depth (8, 10, or 12).
	// +kubebuilder:validation:Required
	ComponentDepth int `json:"component_depth"`

	// Colorspace specifies the color space (BT709, BT2020, etc.).
	// +kubebuilder:validation:Required
	Colorspace string `json:"colorspace"`

	// TransferCharacteristic specifies the transfer characteristic (SDR, HLG, PQ, etc.).
	// +kubebuilder:validation:Required
	TransferCharacteristic string `json:"transfer_characteristic"`
}

// AudioFormat describes audio-specific media parameters.
type AudioFormat struct {
	// MediaType is the IANA media type/subtype for this stream (e.g. audio/L24).
	// +kubebuilder:validation:Required
	MediaType string `json:"media_type"`

	// SampleRate is the audio sample rate in Hz.
	// +kubebuilder:validation:Required
	SampleRate int `json:"sample_rate"`

	// ChannelCount is the number of audio channels.
	// +kubebuilder:validation:Required
	ChannelCount int `json:"channel_count"`

	// SampleDepth is the audio sample depth in bits (e.g. 16, 24).
	// +kubebuilder:validation:Required
	SampleDepth int `json:"sample_depth"`
}

// DataFormat describes data-specific media parameters.
type DataFormat struct {
	// MediaType is the IANA media type/subtype for this stream (e.g. video/smpte291).
	// +kubebuilder:validation:Required
	MediaType string `json:"media_type"`
}

// NMOSControlStatus tracks NMOS identifiers for an input/output port.
type NMOSControlStatus struct {
	// ReceiverID is the NMOS receiver UUID when this port acts as an input.
	// +kubebuilder:validation:Optional
	ReceiverID string `json:"receiver_id,omitempty"`

	// SenderID is the NMOS sender UUID when this port acts as an output.
	// +kubebuilder:validation:Optional
	SenderID string `json:"sender_id,omitempty"`
}

// SDPControlStatus tracks inline SDP control data.
type SDPControlStatus struct {
	// Data contains the SDP payload.
	// +kubebuilder:validation:Optional
	Data string `json:"data,omitempty"`
}

// MXLStaticControlStatus tracks the static MXL flow parameters in use.
type MXLStaticControlStatus struct {
	// MXLDomainID is the MXL domain identifier.
	// +kubebuilder:validation:Optional
	MXLDomainID string `json:"mxl_domain_id,omitempty"`

	// MXLFlowID is the MXL flow identifier.
	// +kubebuilder:validation:Optional
	MXLFlowID string `json:"mxl_flow_id,omitempty"`
}

// ControlStatus tracks the control plane status for an input/output port.
// Exactly one control status variant must be specified.
// +kubebuilder:validation:XValidation:rule="[has(self.nmos),has(self.sdp),has(self.mxl_static)].filter(x,x==true).size() == 1",message="exactly one control status variant (nmos, sdp, or mxl_static) must be set"
type ControlStatus struct {
	// NMOS contains NMOS control status.
	// +kubebuilder:validation:Optional
	NMOS *NMOSControlStatus `json:"nmos,omitempty"`

	// SDP contains inline SDP control status.
	// +kubebuilder:validation:Optional
	SDP *SDPControlStatus `json:"sdp,omitempty"`

	// MXLStatic contains the static MXL flow parameters in use.
	// +kubebuilder:validation:Optional
	MXLStatic *MXLStaticControlStatus `json:"mxl_static,omitempty"`
}

// MediaStatus tracks the status of a single input/output port.
type MediaStatus struct {
	// Control contains the control plane status.
	Control ControlStatus `json:"control"`
}

// Condition types for media function lifecycle.
const (
	ConditionProvisioned = "Provisioned" // Deployment available and pod running
	ConditionConfigured  = "Configured"  // Deployment-time config applied (e.g. SDP ConfigMap)
	ConditionRegistered  = "Registered"  // IS-04 senders/receivers discovered for NMOS-controlled endpoints
	ConditionConnected   = "Connected"   // IS-05 active state or sufficient static I/O configuration
	ConditionActive      = "Active"      // Media is flowing
	ConditionDegraded    = "Degraded"    // Runtime issues (packet loss, processing timeouts, etc.)
)

// BaseStatus contains common status fields for all media functions
type BaseStatus struct {
	// Conditions represent the latest available observations of the resource's state
	// +patchMergeKey=type
	// +patchStrategy=merge
	// +listType=map
	// +listMapKey=type
	Conditions []metav1.Condition `json:"conditions,omitempty" patchStrategy:"merge" patchMergeKey:"type"`

	// Inputs contains the status of each input keyed by input name.
	// +kubebuilder:validation:MaxProperties=32
	Inputs map[string]MediaStatus `json:"inputs,omitempty"`

	// Outputs contains the status of each output keyed by output name.
	// +kubebuilder:validation:MaxProperties=32
	Outputs map[string]MediaStatus `json:"outputs,omitempty"`
}

